-- Historical schema version 13 trigger, before the NULL-comparison fix.
CREATE TRIGGER IF NOT EXISTS agena_sessions_subtask_lifecycle BEFORE UPDATE OF subtask_status, subtask_started_at_ms, subtask_finished_at_ms, subtask_failure_json ON agena_sessions WHEN NEW.relation_kind != 'subagent' OR NEW.subtask_status NOT IN ('created', 'running', 'completed', 'failed', 'cancelled', 'timed_out', 'interrupted') OR (NEW.subtask_status = 'created' AND (NEW.subtask_started_at_ms IS NOT NULL OR NEW.subtask_finished_at_ms IS NOT NULL OR NEW.subtask_failure_json IS NOT NULL)) OR (NEW.subtask_status = 'running' AND (NEW.subtask_started_at_ms IS NULL OR NEW.subtask_finished_at_ms IS NOT NULL OR NEW.subtask_failure_json IS NOT NULL)) OR (NEW.subtask_status = 'completed' AND (NEW.subtask_started_at_ms IS NULL OR NEW.subtask_finished_at_ms IS NULL OR NEW.subtask_failure_json IS NOT NULL)) OR (NEW.subtask_status = 'cancelled' AND (NEW.subtask_started_at_ms IS NULL OR NEW.subtask_finished_at_ms IS NULL OR NEW.subtask_failure_json IS NOT NULL)) OR (NEW.subtask_status IN ('failed', 'timed_out', 'interrupted') AND (NEW.subtask_started_at_ms IS NULL OR NEW.subtask_finished_at_ms IS NULL OR NEW.subtask_failure_json IS NULL OR length(trim(NEW.subtask_failure_json)) = 0 OR CASE WHEN json_valid(NEW.subtask_failure_json) = 1 THEN (json_type(NEW.subtask_failure_json, '$.id') != 'text' OR json_type(NEW.subtask_failure_json, '$.code') != 'text' OR json_type(NEW.subtask_failure_json, '$.user.fallback') != 'text') ELSE 1 END)) OR (NEW.subtask_started_at_ms IS NOT NULL AND NEW.subtask_started_at_ms < 0) OR (NEW.subtask_finished_at_ms IS NOT NULL AND NEW.subtask_finished_at_ms < NEW.subtask_started_at_ms) BEGIN SELECT RAISE(ABORT, 'invalid delegated-task lifecycle'); END;
